  updateStatus(){if(!this.doc)return;const p=this.page(),count=p.layers.reduce((n,l)=>n+l.objects.length,0),cam=p.camera,space=this.spaceMode();$('#statusObjects').textContent=`${count} 個物件`;$('#statusSpace').textContent=space==='layout'?'版面空間':'創作空間';$('#statusArtboard').textContent=`${p.artboard.preset} ${p.artboard.orientation==='portrait'?'直式':'橫式'}`;$('#selectionModeStatus').textContent=this.tool==='select'?`選取：${this.selectionMode==='contain'?'框內':'交集'}`:(this.smartGuides?'智慧吸附':'自由移動');$('#zoomText').textContent=`${Math.round(cam.scale*100)}%`;$('#rotateResetBtn').textContent=`旋轉 ${Math.round(deg(cam.rotation))}°`;this.el.hint.style.display=count||this.draft?'none':'flex';}

