  clearSelection(){this.selection=[];this.refreshSelectionUI();this.renderer.render();}
  deleteSelection(){if(!this.selection.length)return;this.history.pushScoped('刪除物件',[...new Set(this.selectedObjects().map(f=>JSON.stringify(this.layerObjectsPath(f.layer))))].map(x=>JSON.parse(x)),()=>{for(const ref of [...this.selection].reverse()){const f=this.findObject(ref);if(f)f.layer.objects.splice(f.index,1);}this.selection=[];});this.refreshAll();}
  duplicateSelection(offset=18){const found=this.selectedObjects();if(!found.length)return;this.history.pushScoped('複製物件',[...new Set(found.map(f=>JSON.stringify(this.layerObjectsPath(f.layer))))].map(x=>JSON.parse(x)),()=>{const newSel=[];for(const f of found){const copy=deepClone(f.object);this.regenerateIds(copy);copy.matrix=M.multiply(M.translate(offset,offset),copy.matrix);f.layer.objects.splice(f.index+1,0,copy);newSel.push({layerId:f.layer.id,objectId:copy.id});}this.selection=newSel;});this.refreshAll();}
  translateSelection(dx,dy,label='移動物件'){if(!this.selection.length||(!dx&&!dy))return;this.history.pushScoped(label,this.selectionHistoryTargets(),()=>{for(const f of this.selectedObjects())f.object.matrix=M.multiply(M.translate(dx,dy),f.object.matrix);});this.queueSpatialSelection();this.refreshSelectionUI();this.renderer.render();}
  applyTransformField(field,value){if(!Number.isFinite(value)||!this.selection.length)return;const b=this.renderer.selectionWorldBounds();if(!b)return;let t=M.identity(),label='調整物件';if(field==='x')t=M.translate(value-b.x,0);else if(field==='y')t=M.translate(0,value-b.y);else if(field==='w'){const sx=value/Math.max(.0001,b.w),sy=this.aspectLock?sx:1;t=M.around(b.x,b.y,M.scale(sx,sy));}else if(field==='h'){const sy=value/Math.max(.0001,b.h),sx=this.aspectLock?sy:1;t=M.around(b.x,b.y,M.scale(sx,sy));}else if(field==='r'){const selected=this.selectedObjects(),current=selected.length===1?matrixRotation(selected[0].object.matrix):0,delta=rad(value)-current,center={x:b.x+b.w/2,y:b.y+b.h/2};t=M.around(center.x,center.y,M.rotate(delta));label='旋轉物件';}else return;this.history.pushScoped(label,this.selectionHistoryTargets(),()=>{for(const f of this.selectedObjects())f.object.matrix=M.multiply(t,f.object.matrix);});this.queueSpatialSelection();this.refreshSelectionUI();this.renderer.render();}
  alignSelection(mode){const items=this.selectedObjects().map(f=>({...f,b:this.renderer.objectWorldBounds(f.object)}));if(items.length<2)return;const total=items.reduce((b,x)=>unionBounds(b,x.b),null);this.history.pushScoped('對齊物件',this.selectionHistoryTargets(),()=>{if(mode==='distributeX'||mode==='distributeY'){const horizontal=mode==='distributeX',sorted=[...items].sort((a,b)=>horizontal?a.b.x-b.b.x:a.b.y-b.b.y);if(sorted.length>2){const first=sorted[0].b,last=sorted.at(-1).b,totalSize=sorted.reduce((n,x)=>n+(horizontal?x.b.w:x.b.h),0),span=(horizontal?last.x+last.w-first.x:last.y+last.h-first.y),gap=(span-totalSize)/(sorted.length-1);let cursor=horizontal?first.x:first.y;for(const x of sorted){const current=horizontal?x.b.x:x.b.y,delta=cursor-current;x.object.matrix=M.multiply(M.translate(horizontal?delta:0,horizontal?0:delta),x.object.matrix);cursor+=(horizontal?x.b.w:x.b.h)+gap;}}}else for(const x of items){let dx=0,dy=0;if(mode==='left')dx=total.x-x.b.x;else if(mode==='centerX')dx=total.x+total.w/2-(x.b.x+x.b.w/2);else if(mode==='right')dx=total.x+total.w-(x.b.x+x.b.w);else if(mode==='top')dy=total.y-x.b.y;else if(mode==='centerY')dy=total.y+total.h/2-(x.b.y+x.b.h/2);else if(mode==='bottom')dy=total.y+total.h-(x.b.y+x.b.h);x.object.matrix=M.multiply(M.translate(dx,dy),x.object.matrix);}});this.queueSpatialSelection();this.refreshSelectionUI();this.renderer.render();}
  changeObjectOpacity(value,commit){const selected=this.selectedObjects();if(!selected.length)return;if(this.objectOpacityStart==null)this.objectOpacityStart=selected.map(f=>({ref:{layerId:f.layer.id,objectId:f.object.id},value:f.object.opacity??1}));selected.forEach(f=>f.object.opacity=value);$('#objectOpacityOutput').value=`${Math.round(value*100)}%`;this.renderer.render();if(commit){const before=this.objectOpacityStart;this.objectOpacityStart=null;before.forEach(x=>{const f=this.findObject(x.ref);if(f)f.object.opacity=x.value;});this.history.pushScoped('調整物件透明度',this.selectionHistoryTargets(),()=>this.selectedObjects().forEach(f=>f.object.opacity=value));this.renderer.render();}}
  reorderSelection(where){const byLayer=new Map();for(const f of this.selectedObjects()){if(!byLayer.has(f.layer.id))byLayer.set(f.layer.id,[]);byLayer.get(f.layer.id).push(f.object);}if(!byLayer.size)return;this.history.pushScoped(where==='front'?'移至最上':'移至最下',[...byLayer.keys()].map(layerId=>this.layerObjectsPath(this.page().layers.find(l=>l.id===layerId))),()=>{for(const [layerId,objects]of byLayer){const layer=this.page().layers.find(l=>l.id===layerId);layer.objects=layer.objects.filter(o=>!objects.includes(o));if(where==='front')layer.objects.push(...objects);else layer.objects.unshift(...objects);}});this.refreshAll();}
  groupSelection(){const found=this.selectedObjects();if(found.length<2){this.toast('至少選取兩個物件');return;}const layer=found[0].layer;if(found.some(f=>f.layer!==layer)){this.toast('群組物件必須位於同一圖層');return;}this.history.pushScoped('群組物件',[this.layerObjectsPath(layer)],()=>{const indexes=found.map(f=>f.index).sort((a,b)=>a-b),children=indexes.map(i=>layer.objects[i]);layer.objects=layer.objects.filter(o=>!children.includes(o));const group={id:uid(),type:'group',name:'群組',matrix:M.identity(),opacity:1,children};layer.objects.splice(indexes[0],0,group);this.selection=[{layerId:layer.id,objectId:group.id}];});this.refreshAll();}
  ungroupSelection(){const found=this.selectedObjects().filter(f=>f.object.type==='group');if(!found.length){this.toast('未選取群組');return;}this.history.pushScoped('解散群組',[...new Set(found.map(f=>JSON.stringify(this.layerObjectsPath(f.layer))))].map(x=>JSON.parse(x)),()=>{const newSel=[];for(const f of found.reverse()){const children=f.object.children||[];for(const child of children){child.matrix=M.multiply(f.object.matrix,child.matrix);newSel.push({layerId:f.layer.id,objectId:child.id});}f.layer.objects.splice(f.index,1,...children);}this.selection=newSel;});this.refreshAll();}

  changeArtboard(key,value,{fit=true}={}){
    const page=this.page(),before=normalizeArtboard(page.artboard||{}),next=normalizeArtboard({...before,[key]:value});
    if(key==='orientation'||key==='preset'){
      const portrait=next.orientation==='portrait';next.widthMm=portrait?210:297;next.heightMm=portrait?297:210;next.preset='A4';
    }
    if(JSON.stringify(before)===JSON.stringify(next))return;
    this.history.pushScoped('調整畫板',[[...this.pagePath(page),'artboard']],()=>{page.artboard=next;});
    this.renderer.invalidateTiles();this.refreshArtboardUI();this.renderer.render();if(fit&&['orientation','preset'].includes(key))this.fitArtboard({switchSpace:false});
  }
